    // Play sound effect using Web Audio API
    function playChakraChime() {
      try {
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        if (!AudioContext) return;
        const ctx = new AudioContext();
        
        // Tone 1
        const osc1 = ctx.createOscillator();
        const gain1 = ctx.createGain();
        osc1.type = 'sine';
        osc1.frequency.setValueAtTime(587.33, ctx.currentTime);
        osc1.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.15);
        gain1.gain.setValueAtTime(0.12, ctx.currentTime);
        gain1.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.8);
        osc1.connect(gain1);
        gain1.connect(ctx.destination);
        osc1.start();
        osc1.stop(ctx.currentTime + 0.8);

        // Tone 2
        const osc2 = ctx.createOscillator();
        const gain2 = ctx.createGain();
        osc2.type = 'triangle';
        osc2.frequency.setValueAtTime(440, ctx.currentTime);
        gain2.gain.setValueAtTime(0.08, ctx.currentTime);
        gain2.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.6);
        osc2.connect(gain2);
        gain2.connect(ctx.destination);
        osc2.start();
        osc2.stop(ctx.currentTime + 0.6);
      } catch (e) {
        console.log('Audio chime not supported / blocked:', e);
      }
    }

    // Logo Click Creator Toast Trigger
    const brandLogo = document.getElementById("brand-logo");
    const creatorToast = document.getElementById("creator-toast");
    if (brandLogo && creatorToast) {
      brandLogo.addEventListener("click", () => {
        playChakraChime();
        creatorToast.classList.add("show");
        setTimeout(() => {
          creatorToast.classList.remove("show");
        }, 3000); // Fades out after 3 seconds
      });
    }

    // Backlog sem select dropdown change
    const backlogSem = document.getElementById("backlog-sem-select");
    if (backlogSem) {
      backlogSem.addEventListener("change", (e) => {
        populateSubjectsDropdown("backlog-subject-select", parseInt(e.target.value, 10));
      });
    }

    // Add backlog button click
    const addBacklogBtn = document.getElementById("backlog-btn-add");
