  function showSyllabusDetails(subject) {
    const detailPanel = document.getElementById("syllabus-details-panel");
    const detailName = document.getElementById("syllabus-details-name");
    const accordion = document.getElementById("syllabus-accordion");
    
    if (!detailPanel || !detailName || !accordion) return;

    detailName.textContent = `${subject.code} - ${subject.name}`;
    accordion.innerHTML = "";

    if (!subject.units || subject.units.length === 0) {
      accordion.innerHTML = `
        <div style="padding:1.5rem; text-align:center;" class="text-secondary">
          No detailed units available for this subject outline. You can create mock exam practice templates using the Mock Exam portal or add questions via the Contributions section.
        </div>
      `;
      detailPanel.style.display = "block";
      detailPanel.scrollIntoView({ behavior: "smooth" });
      return;
    }

    subject.units.forEach(unit => {
      const item = document.createElement("div");
      item.className = "accordion-item";
      
      item.innerHTML = `
        <div class="accordion-header">
          <div class="accordion-title">
            <span class="unit-number-badge">${unit.number}</span>
            <span>Unit ${unit.number}: ${unit.title}</span>
          </div>
          <svg class="accordion-icon" viewBox="0 0 24 24"><polyline points="6 9 12 15 18 9"></polyline></svg>
        </div>
        <div class="accordion-content">
          <p>${unit.topics}</p>
        </div>
      `;

      // Header click
      item.querySelector(".accordion-header").addEventListener("click", () => {
        const isActive = item.classList.contains("active");
        // Close others
        document.querySelectorAll(".accordion-item").forEach(ai => ai.classList.remove("active"));
        if (!isActive) {
          item.classList.add("active");
        }
      });

      accordion.appendChild(item);
    });

    detailPanel.style.display = "block";
    detailPanel.scrollIntoView({ behavior: "smooth" });
  }

