  // --- QUESTION BANK VIEW ---
  function renderQuestionBank() {
    const select = document.getElementById("qbank-subject-select");
    const displayArea = document.getElementById("qbank-display-area");
    
    if (!select || !displayArea) return;

    const subjectCode = select.value;
    if (!subjectCode) {
      displayArea.innerHTML = `<p class="text-center text-secondary">Please select a subject.</p>`;
      return;
    }

    const subjectObj = findSubjectByCode(subjectCode);
    const standardQB = pharmaData.questionBank[subjectCode] || { "2marks": [], "5marks": [], "10marks": [] };
    
    // Filter user questions for this subject
    const userQB_2 = appState.userQuestions.filter(q => q.subjectCode === subjectCode && q.category === "2");
    const userQB_5 = appState.userQuestions.filter(q => q.subjectCode === subjectCode && q.category === "5");
    const userQB_10 = appState.userQuestions.filter(q => q.subjectCode === subjectCode && q.category === "10");

    // Merge lists
    const q2 = [...standardQB["2marks"], ...userQB_2.map(u => ({ unit: u.unit, text: u.text, isUser: true }))];
    const q5 = [...standardQB["5marks"], ...userQB_5.map(u => ({ unit: u.unit, text: u.text, isUser: true }))];
    const q10 = [...standardQB["10marks"], ...userQB_10.map(u => ({ unit: u.unit, text: u.text, isUser: true }))];

    displayArea.innerHTML = "";

    if (q2.length === 0 && q5.length === 0 && q10.length === 0) {
      displayArea.innerHTML = `
        <div style="text-align:center; padding:2rem;" class="text-secondary">
          No questions populated for ${subjectCode} yet.
          <br><br>
          <a href="#contribute" class="btn btn-secondary btn-sm">Be the first to add questions!</a>
        </div>
      `;
      return;
    }

    // Render Categories
    renderQuestionCategory(displayArea, "Section A: Objective Type Questions", "2", q2);
    renderQuestionCategory(displayArea, "Section B: Long Essay Questions", "10", q10);
    renderQuestionCategory(displayArea, "Section C: Short Answer Questions", "5", q5);
  }

  function renderQuestionCategory(container, title, marks, questions) {
    if (questions.length === 0) return;

    const block = document.createElement("div");
    block.className = `q-category-block marks-${marks}`;
    
    block.innerHTML = `
      <div class="q-category-title">
        <span>${title}</span>
        <span class="q-category-badge">${marks} Marks Each</span>
      </div>
      <ol class="questions-ol"></ol>
    `;

    const ol = block.querySelector("ol");

    questions.forEach(q => {
      const li = document.createElement("li");
      
      let badgeHtml = q.isUser ? `<span class="badge badge-info" style="margin-left:0.5rem; font-size:0.6rem;">Added by You</span>` : "";
      li.innerHTML = `
        ${q.text}
        <span class="q-unit-indicator">Unit ${q.unit}</span>
        ${badgeHtml}
      `;
      ol.appendChild(li);
    });

    container.appendChild(block);
  }

  // --- MOCK EXAM PAPER GENERATOR ---
  function generateMockPaper() {
    const select = document.getElementById("mock-subject-select");
    const paperRoot = document.getElementById("mock-paper-root");
    
    if (!select || !paperRoot) return;

    const subjectCode = select.value;
    if (!subjectCode) return;

    const subject = findSubjectByCode(subjectCode);
    if (!subject) return;

    // Set headers on paper
    document.getElementById("paper-subject-title").textContent = subject.name;
    document.getElementById("paper-subject-code").textContent = subjectCode;
    document.getElementById("paper-sem-number").textContent = getRomanNumeral(appState.currentSemester);

    // Stop existing exam timer if running
    stopExamTimer();

    // Fetch questions
    const standardQB = pharmaData.questionBank[subjectCode] || { "2marks": [], "5marks": [], "10marks": [] };
    const userQB_2 = appState.userQuestions.filter(q => q.subjectCode === subjectCode && q.category === "2").map(q => ({ text: q.text }));
    const userQB_5 = appState.userQuestions.filter(q => q.subjectCode === subjectCode && q.category === "5").map(q => ({ text: q.text }));
    const userQB_10 = appState.userQuestions.filter(q => q.subjectCode === subjectCode && q.category === "10").map(q => ({ text: q.text }));

    const allQ2 = [...standardQB["2marks"], ...userQB_2];
    const allQ5 = [...standardQB["5marks"], ...userQB_5];
    const allQ10 = [...standardQB["10marks"], ...userQB_10];

    const questionsContainer = document.getElementById("paper-questions-container");
    questionsContainer.innerHTML = "";

    // Validation warning if insufficient questions
    if (allQ2.length < 10 || allQ10.length < 3 || allQ5.length < 9) {
      questionsContainer.innerHTML = `
        <div style="background:rgba(245,158,11,0.08); border:1px solid rgba(245,158,11,0.3); color:var(--warning); padding:1.5rem; border-radius:var(--radius-md); font-family:var(--font-body); margin-bottom:1.5rem; line-height:1.6;">
          <strong>Insufficient Questions in database to build a complete 75-mark paper.</strong><br>
          We need at least 10 objective questions, 3 long questions, and 9 short questions.
          <br><br>
          <em>Generating an incomplete/simulated paper using available items:</em>
        </div>
      `;
    }

    // SECTION A (Objective) - 10 compulsory questions of 2 marks
    const sectionAQuestions = shuffleArray([...allQ2]).slice(0, 10);
    renderPaperSection(questionsContainer, "SECTION A", "Answer all the questions", "10 x 2 = 20", sectionAQuestions, 2);

    // SECTION B (Long Answers) - 3 options, answer 2 (10 marks each)
    const sectionBQuestions = shuffleArray([...allQ10]).slice(0, 3);
    renderPaperSection(questionsContainer, "SECTION B", "Answer any TWO of the following", "2 x 10 = 20", sectionBQuestions, 10);

    // SECTION C (Short Answers) - 9 options, answer 7 (5 marks each)
    const sectionCQuestions = shuffleArray([...allQ5]).slice(0, 9);
    renderPaperSection(questionsContainer, "SECTION C", "Answer any SEVEN of the following", "7 x 5 = 35", sectionCQuestions, 5);

    // Show Printable Root
    paperRoot.style.display = "block";
    paperRoot.scrollIntoView({ behavior: "smooth" });

    // Show Save to Vault button
    const mockSaveVaultBtn = document.getElementById("mock-btn-save-vault");
    if (mockSaveVaultBtn) {
      mockSaveVaultBtn.style.display = "inline-block";
    }
  }

  function renderPaperSection(container, secName, instruction, marksTotal, questions, qMark) {
    const secDiv = document.createElement("div");
    secDiv.className = "exam-section";
    
    secDiv.innerHTML = `
      <div class="exam-section-title">
        <span>${secName}</span>
        <span class="exam-section-marks">[${marksTotal}]</span>
      </div>
      <div class="exam-section-instruction">${instruction}:</div>
      <ul class="exam-question-list"></ul>
    `;

    const ul = secDiv.querySelector("ul");

    if (questions.length === 0) {
      const li = document.createElement("li");
      li.className = "text-muted";
      li.textContent = "No questions added yet for this section category. You can write your own exam papers on the Share Questions page.";
      ul.appendChild(li);
    } else {
      questions.forEach((q, idx) => {
        const li = document.createElement("li");
        li.className = "exam-question-item";
        
        li.innerHTML = `
          <div class="exam-question-text">
            <span class="q-number">${idx + 1}.</span>${q.text}
          </div>
          <div class="exam-question-marks">(${qMark})</div>
        `;
        ul.appendChild(li);
      });
    }

    container.appendChild(secDiv);
  }

  // --- EXAM TIMER LOGIC ---
  function startExamTimer() {
    const timerCard = document.getElementById("mock-timer-card");
    const startBtn = document.getElementById("btn-start-exam-timer");
    
    if (!timerCard || !startBtn) return;

    // Reset timer to 3 hours
    appState.examTimeLeft = 10800; 
    appState.examTimerPaused = false;
    
    timerCard.style.display = "flex";
    startBtn.disabled = true;
    startBtn.textContent = "Timer Running...";

    document.getElementById("mock-timer-btn-pause").textContent = "Pause Timer";

    if (appState.examTimerInterval) clearInterval(appState.examTimerInterval);

    appState.examTimerInterval = setInterval(() => {
      if (appState.examTimerPaused) return;

      appState.examTimeLeft--;
      updateExamTimerClock();

      if (appState.examTimeLeft <= 0) {
        clearInterval(appState.examTimerInterval);
        alert("Time is up! Your 3-hour exam practice duration has completed.");
        stopExamTimer();
      }
    }, 1000);

    updateExamTimerClock();
  }

  function updateExamTimerClock() {
    const clock = document.getElementById("exam-timer-clock");
    if (!clock) return;

    const hrs = Math.floor(appState.examTimeLeft / 3600);
    const mins = Math.floor((appState.examTimeLeft % 3600) / 60);
    const secs = appState.examTimeLeft % 60;

    clock.textContent = `${String(hrs).padStart(2, "0")}:${String(mins).padStart(2, "0")}:${String(secs).padStart(2, "0")}`;
  }

  function toggleExamTimer() {
    const pauseBtn = document.getElementById("mock-timer-btn-pause");
    appState.examTimerPaused = !appState.examTimerPaused;
    
    if (pauseBtn) {
      pauseBtn.textContent = appState.examTimerPaused ? "Resume Timer" : "Pause Timer";
      pauseBtn.classList.toggle("btn-primary");
    }
  }

  function stopExamTimer() {
    if (appState.examTimerInterval) {
      clearInterval(appState.examTimerInterval);
      appState.examTimerInterval = null;
    }

    const timerCard = document.getElementById("mock-timer-card");
    const startBtn = document.getElementById("btn-start-exam-timer");
    
    if (timerCard) timerCard.style.display = "none";
    if (startBtn) {
      startBtn.disabled = false;
      startBtn.textContent = "Start 3-Hour Practice";
    }
  }

  // --- GPAT INTERACTIVE QUIZ ENGINE ---
  function startMcqQuiz() {
    const select = document.getElementById("quiz-subject-select");
    const initControls = document.getElementById("quiz-init-controls");
    const playArea = document.getElementById("quiz-play-area");
    const resultArea = document.getElementById("quiz-result-area");
    
    if (!select || !initControls || !playArea || !resultArea) return;

    const subjectCode = select.value;
    if (!subjectCode) {
      alert("Please select a subject course to begin.");
      return;
    }

    const mcqs = pharmaData.mcqDatabase[subjectCode] || [];
    if (mcqs.length === 0) {
      alert(`No practice MCQs found in database for ${subjectCode}. Start logging some questions or practice using the sessional question sheets.`);
      return;
    }

    // Prepare quiz states
    appState.quizQuestions = shuffleArray([...mcqs]).slice(0, 10); // Pick 10 random
    appState.quizCurrentIndex = 0;
    appState.quizScore = 0;
    appState.quizSelectedAnswer = null;
    appState.quizActive = true;
    appState.quizTimeElapsed = 0;

    initControls.style.display = "none";
    resultArea.style.display = "none";
    playArea.style.display = "block";

    // Setup timer
    if (appState.quizTimerInterval) clearInterval(appState.quizTimerInterval);
    appState.quizTimerInterval = setInterval(() => {
      appState.quizTimeElapsed++;
      const mins = Math.floor(appState.quizTimeElapsed / 60);
      const secs = appState.quizTimeElapsed % 60;
      const timerSpan = document.getElementById("quiz-timer-span");
      if (timerSpan) {
        timerSpan.textContent = `Time: ${String(mins).padStart(2, "0")}:${String(secs).padStart(2, "0")}`;
      }
    }, 1000);

    renderQuizQuestion();
  }

  function renderQuizQuestion() {
    const qObj = appState.quizQuestions[appState.quizCurrentIndex];
    if (!qObj) return;

    appState.quizSelectedAnswer = null;

    // Progress updates
    const currentNum = document.getElementById("quiz-current-num");
    const totalNum = document.getElementById("quiz-total-num");
    const progressFill = document.getElementById("quiz-progress-fill");
    
    if (currentNum) currentNum.textContent = appState.quizCurrentIndex + 1;
    if (totalNum) totalNum.textContent = appState.quizQuestions.length;
    if (progressFill) {
      const percentage = ((appState.quizCurrentIndex) / appState.quizQuestions.length) * 100;
      progressFill.style.width = `${percentage}%`;
    }

    // Set text
    document.getElementById("quiz-question-text").textContent = qObj.question;

    // Reset controls
    const prevBtn = document.getElementById("quiz-btn-prev");
    const nextBtn = document.getElementById("quiz-btn-next");
    if (prevBtn) prevBtn.disabled = appState.quizCurrentIndex === 0;
    if (nextBtn) nextBtn.textContent = appState.quizCurrentIndex === appState.quizQuestions.length - 1 ? "Finish Quiz" : "Next Question";

    // Hide explanations
    document.getElementById("quiz-explanation-box").style.display = "none";

    // Options mapping
    const optionsContainer = document.getElementById("quiz-options-container");
    optionsContainer.innerHTML = "";

    qObj.options.forEach((optText, optIdx) => {
      const btn = document.createElement("button");
      btn.className = "quiz-option-btn";
      
      const letter = String.fromCharCode(65 + optIdx); // A, B, C, D
      btn.innerHTML = `
        <span class="option-letter">${letter}</span>
        <span>${optText}</span>
      `;

      btn.addEventListener("click", () => {
        if (appState.quizSelectedAnswer !== null) return; // Answer already selected
        handleQuizSelection(optIdx, btn);
      });

      optionsContainer.appendChild(btn);
    });
  }

  function handleQuizSelection(selectedIdx, buttonElement) {
    appState.quizSelectedAnswer = selectedIdx;
    const qObj = appState.quizQuestions[appState.quizCurrentIndex];
    
    const optionsContainer = document.getElementById("quiz-options-container");
    const optionButtons = optionsContainer.querySelectorAll(".quiz-option-btn");

    if (selectedIdx === qObj.answer) {
      // Correct answer
      buttonElement.classList.add("correct");
      appState.quizScore++;
    } else {
      // Incorrect answer
      buttonElement.classList.add("incorrect");
      // Highlight the correct one
      if (optionButtons[qObj.answer]) {
        optionButtons[qObj.answer].classList.add("correct");
      }
    }

    // Show Explanation
    const explanationBox = document.getElementById("quiz-explanation-box");
    const explanationTxt = document.getElementById("quiz-explanation-text");
    if (explanationBox && explanationTxt) {
      explanationTxt.textContent = qObj.explanation || "No detailed analytical explanation stored for this mock item.";
      explanationBox.style.display = "block";
    }
  }

  function handleQuizNext() {
    if (appState.quizSelectedAnswer === null) {
      alert("Please select an option before moving to the next question.");
      return;
    }

    if (appState.quizCurrentIndex < appState.quizQuestions.length - 1) {
      appState.quizCurrentIndex++;
      renderQuizQuestion();
    } else {
      finishQuiz();
    }
  }

  function handleQuizPrev() {
    if (appState.quizCurrentIndex > 0) {
      appState.quizCurrentIndex--;
      renderQuizQuestion();
    }
  }

  function finishQuiz() {
    if (appState.quizTimerInterval) {
      clearInterval(appState.quizTimerInterval);
      appState.quizTimerInterval = null;
    }

    appState.quizActive = false;

    const playArea = document.getElementById("quiz-play-area");
    const resultArea = document.getElementById("quiz-result-area");
    
    if (playArea) playArea.style.display = "none";
    if (resultArea) resultArea.style.display = "block";

    const resultScore = document.getElementById("result-score-txt");
    if (resultScore) {
      resultScore.textContent = `${appState.quizScore}/${appState.quizQuestions.length}`;
    }

    const feedback = document.getElementById("result-feedback-txt");
    if (feedback) {
      const pct = (appState.quizScore / appState.quizQuestions.length) * 100;
      if (pct >= 80) {
        feedback.textContent = `Outstanding! Score: ${pct}%. You possess a highly competitive academic foundation. Perfect for GPAT preparations!`;
      } else if (pct >= 50) {
        feedback.textContent = `Good Job! Score: ${pct}%. You have passed. Keep working on revision points to strengthen your concepts.`;
      } else {
        feedback.textContent = `Keep Learning! Score: ${pct}%. Review the syllabus structure and practice writing core answers in the Question Bank.`;
      }
    }
  }

  function quitMcqQuiz() {
    if (appState.quizTimerInterval) {
      clearInterval(appState.quizTimerInterval);
      appState.quizTimerInterval = null;
    }
    appState.quizActive = false;
    
    document.getElementById("quiz-play-area").style.display = "none";
    document.getElementById("quiz-result-area").style.display = "none";
    document.getElementById("quiz-init-controls").style.display = "flex";
  }

  // --- STUDY TRACKER & NOTES ---
  function renderStudyTracker() {
    const container = document.getElementById("tracker-subjects-container");
    if (!container) return;

    const semData = pharmaData.semesters[appState.currentSemester];
    container.innerHTML = "";

    if (semData.subjects.length === 0) {
      container.innerHTML = `<p class="text-center text-secondary">No subjects mapped for this semester.</p>`;
      return;
    }

    semData.subjects.forEach(sub => {
      // Calculate checked progress for this subject
      let compCount = 0;
      for (let unit = 1; unit <= 5; unit++) {
        if (appState.studyProgress[`${sub.code}-unit${unit}`]) {
          compCount++;
        }
      }
      const pct = Math.round((compCount / 5) * 100);

      const card = document.createElement("div");
      card.className = "glass-panel subject-tracker-card";
      
      card.innerHTML = `
        <div class="tracker-title-row">
          <div>
            <span class="subject-code-tag" style="margin-right:0.5rem;">${sub.code}</span>
            <span class="subject-name-txt" style="font-size:1.15rem;">${sub.name}</span>
          </div>
        </div>

        <div class="tracker-progress-wrapper">
          <div class="tracker-bar">
            <div class="tracker-bar-fill" id="fill-${sub.code}" style="width: ${pct}%;"></div>
          </div>
          <div class="tracker-percentage" id="pct-${sub.code}">${pct}%</div>
        </div>

        <div class="units-check-grid" id="grid-${sub.code}">
          <!-- checkboxes -->
        </div>

        <div class="tracker-notes-area">
          <label style="font-size:0.75rem; font-weight:700; color:var(--text-secondary);">Your Study & Revision Notes</label>
          <textarea id="notes-${sub.code}" placeholder="Type important chemical formulas, physiological pathways, or exam topics you need to revise...">${appState.studyNotes[sub.code] || ""}</textarea>
        </div>
      `;

      // Render Checkboxes
      const grid = card.querySelector(`#grid-${sub.code}`);
      for (let unit = 1; unit <= 5; unit++) {
        const checkCard = document.createElement("div");
        const isChecked = appState.studyProgress[`${sub.code}-unit${unit}`] || false;
        
        checkCard.className = `unit-checkbox-card ${isChecked ? 'checked' : ''}`;
        checkCard.innerHTML = `
          <h5>Unit ${unit}</h5>
          <span>${isChecked ? 'Covered' : 'Pending'}</span>
        `;

        checkCard.addEventListener("click", () => {
          const key = `${sub.code}-unit${unit}`;
          const currentVal = appState.studyProgress[key] || false;
          appState.studyProgress[key] = !currentVal;
          saveToStorage("study_progress", appState.studyProgress);

          // Update checkbox state
          checkCard.classList.toggle("checked");
          checkCard.querySelector("span").textContent = !currentVal ? "Covered" : "Pending";

          // Recalculate subject percentage
          let newComp = 0;
          for (let u = 1; u <= 5; u++) {
            if (appState.studyProgress[`${sub.code}-unit${u}`]) newComp++;
          }
          const newPct = Math.round((newComp / 5) * 100);
          card.querySelector(`#fill-${sub.code}`).style.width = `${newPct}%`;
          card.querySelector(`#pct-${sub.code}`).textContent = `${newPct}%`;
          
          updateStats();
        });

        grid.appendChild(checkCard);
      }

      // Notes event handler
      const notesArea = card.querySelector(`#notes-${sub.code}`);
      notesArea.addEventListener("input", (e) => {
        appState.studyNotes[sub.code] = e.target.value;
        saveToStorage("study_notes", appState.studyNotes);
      });

      container.appendChild(card);
    });
  }

  // --- SHARE QUESTIONS FORM (LOCAL DATABASE) ---
  function renderContributedQuestions() {
    const tbody = document.getElementById("contrib-questions-tbody");
    if (!tbody) return;

    tbody.innerHTML = "";

    if (appState.userQuestions.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="6" class="text-center text-secondary" style="padding:2rem;">
            No questions contributed yet. Help grow your exam paper generator database by logging questions!
          </td>
        </tr>
      `;
      return;
    }

    appState.userQuestions.forEach((q, idx) => {
      const tr = document.createElement("tr");
      
      let catText = "";
      if (q.category === "2") catText = "2 Marks (Objective)";
      else if (q.category === "5") catText = "5 Marks (Short Answer)";
      else if (q.category === "10") catText = "10 Marks (Long Essay)";

      tr.innerHTML = `
        <td>Semester ${getRomanNumeral(q.semester)}</td>
        <td><span class="subject-code-tag">${q.subjectCode}</span></td>
        <td>Unit ${q.unit}</td>
        <td>${catText}</td>
        <td>${q.text}</td>
        <td class="text-center">
          <button class="btn btn-danger btn-sm" style="padding:0.25rem 0.5rem;" data-id="${q.id}">Delete</button>
        </td>
      `;

      tr.querySelector("button").addEventListener("click", () => {
        deleteContributedQuestion(q.id);
      });

      tbody.appendChild(tr);
    });
  }

  function saveContributedQuestion() {
    const semester = parseInt(document.getElementById("contrib-sem-select").value, 10);
    const subjectCode = document.getElementById("contrib-subject-select").value;
    const unit = parseInt(document.getElementById("contrib-unit-select").value, 10);
    const category = document.getElementById("contrib-marks-select").value;
    const text = document.getElementById("contrib-question-text").value.trim();

    if (!subjectCode || !text) {
      alert("Please fill out all required fields.");
      return;
    }

    const newQ = {
      id: Date.now().toString(),
      semester,
      subjectCode,
      unit,
      category,
      text
    };

    appState.userQuestions.push(newQ);
    saveToStorage("user_questions", appState.userQuestions);
    
    // Clear question text
    document.getElementById("contrib-question-text").value = "";
    
    renderContributedQuestions();
    updateStats();
    alert("Question recorded successfully! It has been added to your local practice bank.");
  }

  function deleteContributedQuestion(id) {
    if (confirm("Are you sure you want to delete this question? It will be removed from your mock exam database.")) {
      appState.userQuestions = appState.userQuestions.filter(q => q.id !== id);
      saveToStorage("user_questions", appState.userQuestions);
      renderContributedQuestions();
      updateStats();
    }
  }

