  // --- UTILS ---
  function getRomanNumeral(num) {
    const map = { 1: "I", 2: "II", 3: "III", 4: "IV", 5: "V", 6: "VI", 7: "VII", 8: "VIII" };
    return map[num] || num.toString();
  }

  function findSubjectByCode(code) {
    for (let sem in pharmaData.semesters) {
      const sub = pharmaData.semesters[sem].subjects.find(s => s.code === code);
      if (sub) return sub;
    }
    return null;
  }

  function shuffleArray(array) {
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
  }

  // --- BACKLOG SUBJECTS TRACKER ---
  function initBacklogForm() {
    const semSelect = document.getElementById("backlog-sem-select");
    if (semSelect) {
      populateSubjectsDropdown("backlog-subject-select", parseInt(semSelect.value, 10));
    }
    renderBacklogTracker();
  }

  function addBacklogSubject() {
    const semester = parseInt(document.getElementById("backlog-sem-select").value, 10);
    const subjectCode = document.getElementById("backlog-subject-select").value;

    if (!subjectCode) {
      alert("Please select a subject to add.");
      return;
    }

    // Check if already logged as backlog
    if (appState.backlogSubjects.some(b => b.code === subjectCode)) {
      alert("This subject is already logged as a backlog.");
      return;
    }

    const subjectObj = findSubjectByCode(subjectCode);
    if (!subjectObj) return;

    const newBacklog = {
      code: subjectCode,
      name: subjectObj.name,
      semester: semester,
      progress: {
        unit1: false,
        unit2: false,
        unit3: false,
        unit4: false,
        unit5: false
      },
      notes: ""
    };

    appState.backlogSubjects.push(newBacklog);
    saveToStorage("backlogs", appState.backlogSubjects);
    
    renderBacklogTracker();
    alert(`Backlog tracker established for ${subjectCode}!`);
  }

  function deleteBacklogSubject(code) {
    if (confirm(`Are you sure you want to remove ${code} from your backlog tracker?`)) {
      appState.backlogSubjects = appState.backlogSubjects.filter(b => b.code !== code);
      saveToStorage("backlogs", appState.backlogSubjects);
      renderBacklogTracker();
    }
  }

