  // --- WEEKLY STUDY PLANNER CONTROLLER ---
  
  // Helpers
  function getSubjectClass(code) {
    if (!code) return "general";
    const c = code.toLowerCase();
    if (c === "revision") return "revision";
    if (c === "mcq") return "mcq";
    if (c.includes("101") || c.includes("201") || c.includes("hap")) return "anatomy";
    if (c.includes("203") || c.includes("biochem")) return "biochem";
    if (c.includes("103") || c.includes("pharmaceutics")) return "pharmaceutics";
    if (c.includes("202") || c.includes("301") || c.includes("401") || c.includes("chem")) return "chemistry";
    if (c.includes("404") || c.includes("pharma")) return "pharma";
    return "general";
  }

  function getSubjectLabel(code) {
    if (code === "REVISION") return "Revision";
    if (code === "MCQ") return "MCQ Practice";
    if (code === "GENERAL") return "General";
    return code;
  }

  function getActiveSubjects() {
    const sem = appState.currentSemester || 1;
    console.log("[DIAGNOSTIC] getActiveSubjects called. sem =", sem, "appState.currentSemester =", appState.currentSemester, "pharmaData.semesters[sem] exists =", !!(pharmaData && pharmaData.semesters && pharmaData.semesters[sem]));
    const semData = pharmaData.semesters[sem];
    if (semData && semData.subjects) {
      return semData.subjects;
    }
    return [];
  }

