  // --- CHAKRA POMODORO FOCUS TIMER ---
  function updateFocusStatsDisplay() {
    const sessionCountEl = document.getElementById("pomodoro-sessions-today");
    if (sessionCountEl) {
      sessionCountEl.textContent = appState.focusSessionsToday;
    }
  }

  function playFocusChime(type) {
    try {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) return;
      const ctx = new AudioContext();

      if (type === 'start') {
        // Play a bright rising C-Major chord chime
        const frequencies = [261.63, 329.63, 392.00, 523.25]; // C4, E4, G4, C5
        frequencies.forEach((freq, idx) => {
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.type = 'sine';
          osc.frequency.setValueAtTime(freq, ctx.currentTime + idx * 0.08);
          gain.gain.setValueAtTime(0.08, ctx.currentTime + idx * 0.08);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx * 0.08 + 0.6);
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.start(ctx.currentTime + idx * 0.08);
          osc.stop(ctx.currentTime + idx * 0.08 + 0.6);
        });
      } else if (type === 'complete') {
        // Play a high double-bell chime
        const playBell = (delay) => {
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.type = 'triangle';
          osc.frequency.setValueAtTime(880, ctx.currentTime + delay);
          gain.gain.setValueAtTime(0.12, ctx.currentTime + delay);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + delay + 1.2);
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.start(ctx.currentTime + delay);
          osc.stop(ctx.currentTime + delay + 1.2);
        };
        playBell(0);
        playBell(0.35); // Second ring shortly after
      }
    } catch (e) {
      console.log('Web Audio focus chime blocked/unsupported:', e);
    }
  }

  function initFocusTimerController() {
    const clockEl = document.getElementById("pomodoro-clock-display");
    const modeLabelEl = document.getElementById("pomodoro-mode-display");
    const playBtn = document.getElementById("pomodoro-btn-play");
    const resetBtn = document.getElementById("pomodoro-btn-reset");
    const chakraWrapperEl = document.querySelector(".pomodoro-chakra-wrapper");
    const chakraLogoEl = document.getElementById("pomodoro-chakra-logo");

    const studyBtn = document.getElementById("pomodoro-btn-study");
    const shortBtn = document.getElementById("pomodoro-btn-short");
    const longBtn = document.getElementById("pomodoro-btn-long");
    const customSetBtn = document.getElementById("pomodoro-btn-custom-set");
    const customMinInput = document.getElementById("pomodoro-custom-min");

    if (!clockEl || !playBtn) return;

    function formatTime(seconds) {
      const m = Math.floor(seconds / 60).toString().padStart(2, '0');
      const s = (seconds % 60).toString().padStart(2, '0');
      return `${m}:${s}`;
    }

    function updateClockDisplay() {
      clockEl.textContent = formatTime(appState.focusTimeLeft);
    }

    function setMode(mode, duration, buttonEl, labelText) {
      // Clear interval if active
      if (appState.focusInterval) {
        clearInterval(appState.focusInterval);
        appState.focusInterval = null;
      }
      
      appState.focusMode = mode;
      appState.focusDuration = duration;
      appState.focusTimeLeft = duration;
      appState.focusRunning = false;

      // Update button classes
      [studyBtn, shortBtn, longBtn].forEach(btn => {
        if (btn) btn.classList.remove("active");
      });
      if (buttonEl) buttonEl.classList.add("active");

      // Update text displays
      if (modeLabelEl) modeLabelEl.textContent = labelText;
      updateClockDisplay();

      // Reset animations
      playBtn.textContent = `Start ${mode === 'study' || mode === 'custom' ? 'Study' : 'Break'} ⚡`;
      playBtn.className = "btn btn-primary btn-lg";
      if (chakraWrapperEl) chakraWrapperEl.classList.remove("running");
      if (chakraLogoEl) chakraLogoEl.classList.remove("running");
    }

    if (studyBtn) {
      studyBtn.addEventListener("click", () => {
        setMode("study", 1500, studyBtn, "Study Block");
      });
    }

    if (shortBtn) {
      shortBtn.addEventListener("click", () => {
        setMode("short", 300, shortBtn, "Short Break");
      });
    }

    if (longBtn) {
      longBtn.addEventListener("click", () => {
        setMode("long", 900, longBtn, "Long Break");
      });
    }

    if (customSetBtn && customMinInput) {
      customSetBtn.addEventListener("click", () => {
        const val = parseInt(customMinInput.value, 10);
        if (isNaN(val) || val < 1 || val > 180) {
          alert("Please enter a study duration between 1 and 180 minutes.");
          return;
        }
        setMode("custom", val * 60, null, "Custom Session");
      });
    }

    if (resetBtn) {
      resetBtn.addEventListener("click", () => {
        setMode(appState.focusMode, appState.focusDuration, 
                appState.focusMode === 'study' ? studyBtn : (appState.focusMode === 'short' ? shortBtn : (appState.focusMode === 'long' ? longBtn : null)),
                appState.focusMode === 'study' ? "Study Block" : (appState.focusMode === 'short' ? "Short Break" : (appState.focusMode === 'long' ? "Long Break" : "Custom Session")));
      });
    }

    if (playBtn) {
      playBtn.addEventListener("click", () => {
        if (appState.focusRunning) {
          // Pause
          appState.focusRunning = false;
          if (appState.focusInterval) {
            clearInterval(appState.focusInterval);
            appState.focusInterval = null;
          }
          playBtn.textContent = "Resume ▶️";
          playBtn.className = "btn btn-accent btn-lg";
          
          if (chakraWrapperEl) chakraWrapperEl.classList.remove("running");
          if (chakraLogoEl) chakraLogoEl.classList.remove("running");
        } else {
          // Start
          appState.focusRunning = true;
          playBtn.textContent = "Pause ⏸️";
          playBtn.className = "btn btn-secondary btn-lg";
          
          if (chakraWrapperEl) chakraWrapperEl.classList.add("running");
          if (chakraLogoEl) chakraLogoEl.classList.add("running");

          // Play start sound
          playFocusChime('start');

          appState.focusInterval = setInterval(() => {
            appState.focusTimeLeft--;
            updateClockDisplay();

            if (appState.focusTimeLeft <= 0) {
              clearInterval(appState.focusInterval);
              appState.focusInterval = null;
              appState.focusRunning = false;

              // Play complete sound
              playFocusChime('complete');

              if (appState.focusMode === 'study' || appState.focusMode === 'custom') {
                appState.focusSessionsToday++;
                localStorage.setItem("arx_focus_sessions", appState.focusSessionsToday.toString());
                
                // Increment lifetime focus sessions
                appState.lifetimeFocusSessions = (appState.lifetimeFocusSessions || 0) + 1;
                localStorage.setItem("arx_lifetime_focus", appState.lifetimeFocusSessions.toString());
                
                updateFocusStatsDisplay();
                updateNinjaRank(); // Recalculate rank

                alert("Study session completed! Great work! Take a break.");
                // Switch to short break
                setMode("short", 300, shortBtn, "Short Break");
              } else {
                alert("Break is over! Ready for the next study block?");
                // Switch to study
                setMode("study", 1500, studyBtn, "Study Block");
              }
            }
          }, 1000);
        }
      });
    }

    // Initial load sync
    updateClockDisplay();
    updateFocusStatsDisplay();
  }

  // --- SHINOBI RANK BOARD (Gamification) ---
  function updateNinjaRank() {
    let checkedUnitsCount = 0;
    for (let key in appState.studyProgress) {
      if (appState.studyProgress[key]) {
        checkedUnitsCount++;
      }
    }

    const focusSessionsCount = appState.lifetimeFocusSessions || 0;
    const contributedQuestionsCount = appState.userQuestions ? appState.userQuestions.length : 0;

    const xp = (checkedUnitsCount * 15) + (focusSessionsCount * 25) + (contributedQuestionsCount * 30);

    let rankName = "Academy Student 🎓";
    let rankClass = "rank-academy";
    let nextRankName = "Genin 🥷";
    let nextRankXp = 150;
    let minXp = 0;

    if (xp < 150) {
      rankName = "Academy Student 🎓";
      rankClass = "rank-academy";
      nextRankName = "Genin 🥷";
      nextRankXp = 150;
      minXp = 0;
    } else if (xp < 400) {
      rankName = "Genin 🥷";
      rankClass = "rank-genin";
      nextRankName = "Chunin 🛡️";
      nextRankXp = 400;
      minXp = 150;
    } else if (xp < 800) {
      rankName = "Chunin 🛡️";
      rankClass = "rank-chunin";
      nextRankName = "Jonin ⚡";
      nextRankXp = 800;
      minXp = 400;
    } else if (xp < 1500) {
      rankName = "Jonin ⚡";
      rankClass = "rank-jonin";
      nextRankName = "Hokage 👑";
      nextRankXp = 1500;
      minXp = 800;
    } else {
      rankName = "Hokage 👑";
      rankClass = "rank-hokage";
      nextRankName = "Max Rank reached!";
      nextRankXp = xp;
      minXp = 1500;
    }

    // Update UI elements
    const badgeEl = document.getElementById("ninja-rank-badge");
    const fillEl = document.getElementById("ninja-xp-fill");
    const labelEl = document.getElementById("ninja-xp-label");
    const nextEl = document.getElementById("ninja-next-rank");

    if (badgeEl) {
      badgeEl.textContent = rankName;
      // Reset classes
      badgeEl.className = "badge " + rankClass;
    }

    if (labelEl) {
      if (xp >= 1500) {
        labelEl.textContent = `${xp} XP (Hokage)`;
      } else {
        labelEl.textContent = `${xp} / ${nextRankXp} XP`;
      }
    }

    if (nextEl) {
      if (xp >= 1500) {
        nextEl.textContent = "Max Rank 👑";
      } else {
        nextEl.textContent = `Next: ${nextRankName}`;
      }
    }

    if (fillEl) {
      let pct = 0;
      if (xp >= 1500) {
        pct = 100;
      } else {
        const range = nextRankXp - minXp;
        const current = xp - minXp;
        pct = Math.round((current / range) * 100);
      }
      fillEl.style.width = `${pct}%`;
    }
  }

  // --- AUDIO PRONUNCIATION GUIDE ---
  function speakText(text) {
    if (!('speechSynthesis' in window)) {
      console.warn("Speech synthesis not supported in this browser.");
      return;
    }
    // Cancel any ongoing speech
    window.speechSynthesis.cancel();
    
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.rate = 0.85; // Slow down slightly for clarity on medical terminology
    
    // Attempt to bind an English voice if available
    const voices = window.speechSynthesis.getVoices();
    if (voices && voices.length > 0) {
      const englishVoice = voices.find(v => v.lang.includes('en-US') || v.lang.includes('en-GB') || v.lang.startsWith('en'));
      if (englishVoice) {
        utterance.voice = englishVoice;
      }
    }
    
    window.speechSynthesis.speak(utterance);
  }

