  let scrollsActiveFilter = "all";
  let scrollsSearchQuery = "";

  function initScrollsView() {
    renderSuffixSpellbook();
    renderScrollsGrid();
    setupScrollsListeners();
  }

  function renderSuffixSpellbook() {
    const grid = document.getElementById("suffix-spellbook-grid");
    if (!grid) return;

    // Filter unique suffixes
    const suffixes = pharmacologyScrolls.map(item => ({
      suffix: item.suffix,
      categoryName: item.categoryName,
      id: item.id
    }));

    grid.innerHTML = suffixes.map(s => `
      <div class="suffix-card" data-scroll-id="${s.id}" data-suffix="${s.suffix}">
        <span class="suffix-name">${s.suffix}</span>
        <span class="suffix-class">${s.categoryName}</span>
      </div>
    `).join('');

    // Suffix card click handler
    grid.querySelectorAll(".suffix-card").forEach(card => {
      card.addEventListener("click", () => {
        const suffix = card.getAttribute("data-suffix");
        const scrollId = card.getAttribute("data-scroll-id");
        
        // Update search input and search query state
        const searchInput = document.getElementById("scrolls-search-input");
        if (searchInput) {
          searchInput.value = suffix;
          scrollsSearchQuery = suffix.toLowerCase();
        }
        
        // Reset tabs to 'all' because the search query will find the card
        scrollsActiveFilter = "all";
        const tabsContainer = document.getElementById("scrolls-filter-tabs");
        if (tabsContainer) {
          tabsContainer.querySelectorAll("button").forEach(btn => {
            btn.classList.remove("active");
            if (btn.getAttribute("data-filter") === "all") {
              btn.classList.add("active");
            }
          });
        }
        
        // Render and expand the scroll card
        renderScrollsGrid(scrollId);
      });
    });
  }

  function renderScrollsGrid(expandId = null) {
    const grid = document.getElementById("scrolls-grid");
    if (!grid) return;

    // Filter list
    const filtered = pharmacologyScrolls.filter(scroll => {
      const matchFilter = scrollsActiveFilter === "all" || scroll.category === scrollsActiveFilter;
      const matchSearch = !scrollsSearchQuery || 
        scroll.name.toLowerCase().includes(scrollsSearchQuery) ||
        scroll.suffix.toLowerCase().includes(scrollsSearchQuery) ||
        scroll.categoryName.toLowerCase().includes(scrollsSearchQuery) ||
        scroll.drugs.some(d => d.toLowerCase().includes(scrollsSearchQuery)) ||
        scroll.mechanism.toLowerCase().includes(scrollsSearchQuery);
      return matchFilter && matchSearch;
    });

    if (filtered.length === 0) {
      grid.innerHTML = `<p class="text-center text-secondary" style="grid-column: 1/-1; padding: 2rem;">No scrolls found matching your filters.</p>`;
      return;
    }

    grid.innerHTML = filtered.map(scroll => {
      const isExpanded = expandId === scroll.id;
      return `
        <div class="scroll-card ${isExpanded ? 'expanded' : ''}" id="scroll-card-${scroll.id}" data-id="${scroll.id}">
          <div class="scroll-header">
            <span class="scroll-category">${scroll.categoryName} System</span>
            <h3>${scroll.name}</h3>
            <span class="scroll-suffix-badge">Suffix stem: ${scroll.suffix}</span>
          </div>
          
          <div class="scroll-details">
            <div class="scroll-detail-section">
              <h5>🌀 Jutsu Theory (Mechanism)</h5>
              <p>${scroll.mechanism}</p>
            </div>
            
            <div class="scroll-detail-section">
              <h5>🥷 Ninja Roster (Key Drugs)</h5>
              <p>${scroll.drugs.join(', ')}</p>
            </div>
            
            <div class="scroll-detail-section">
              <h5>⚡ Backlash (Side Effects)</h5>
              <ul>
                ${scroll.sideEffects.map(se => `<li>${se}</li>`).join('')}
              </ul>
            </div>
            
            <div class="scroll-detail-section">
              <h5>🚫 Forbidden Seals (Contraindications)</h5>
              <ul>
                ${scroll.contraindications.map(c => `<li>${c}</li>`).join('')}
              </ul>
            </div>
          </div>
        </div>
      `;
    }).join('');

    // Card expand click handler
    grid.querySelectorAll(".scroll-card").forEach(card => {
      card.addEventListener("click", (e) => {
        if (card.classList.contains("expanded") && e.target.closest(".scroll-details")) {
          return;
        }
        
        const cardId = card.getAttribute("data-id");
        const alreadyExpanded = card.classList.contains("expanded");
        
        grid.querySelectorAll(".scroll-card").forEach(c => c.classList.remove("expanded"));
        
        if (!alreadyExpanded) {
          card.classList.add("expanded");
          card.scrollIntoView({ behavior: "smooth", block: "nearest" });
        }
      });
    });

    if (expandId) {
      setTimeout(() => {
        const targetCard = document.getElementById(`scroll-card-${expandId}`);
        if (targetCard) {
          targetCard.classList.add("expanded");
          targetCard.scrollIntoView({ behavior: "smooth", block: "center" });
        }
      }, 100);
    }
  }

  function setupScrollsListeners() {
    const searchInput = document.getElementById("scrolls-search-input");
    if (searchInput) {
      const newSearch = searchInput.cloneNode(true);
      searchInput.replaceWith(newSearch);
      newSearch.addEventListener("input", (e) => {
        scrollsSearchQuery = e.target.value.trim().toLowerCase();
        renderScrollsGrid();
      });
    }

    const tabsContainer = document.getElementById("scrolls-filter-tabs");
    if (tabsContainer) {
      tabsContainer.querySelectorAll("button").forEach(btn => {
        btn.addEventListener("click", (e) => {
          tabsContainer.querySelectorAll("button").forEach(b => b.classList.remove("active"));
          btn.classList.add("active");
          scrollsActiveFilter = btn.getAttribute("data-filter");
          renderScrollsGrid();
        });
      });
    }
  }

  // --- ANBU EXAM ARCHIVES (VAULT) FUNCTIONS ---

  function showToast(message, type = "success") {
    const toast = document.createElement("div");
    toast.className = "pq-toast show";
    toast.style.boxShadow = type === "danger" 
      ? "0 10px 40px rgba(0, 0, 0, 0.5), 0 0 30px rgba(220, 38, 38, 0.25)"
      : "0 10px 40px rgba(0, 0, 0, 0.5), 0 0 30px rgba(188, 113, 255, 0.25)";
    if (type === "danger") {
      toast.style.borderColor = "var(--danger)";
    } else {
      toast.style.borderColor = "var(--primary)";
    }
    toast.innerHTML = `<span style="background: none; -webkit-text-fill-color: initial; color: inherit;">${message}</span>`;
    document.body.appendChild(toast);
    
    setTimeout(() => {
      toast.classList.remove("show");
      setTimeout(() => {
        toast.remove();
      }, 300);
    }, 2500);
  }

  function saveExamToVault(type, code, name, questionsHtml, details = {}) {
    const id = "exam_" + Date.now() + "_" + Math.random().toString(36).substr(2, 9);
    const newExam = {
      id: id,
      type: type, // "Mock Exam", "Memory Paper", "Manual Sessional", "Imported"
      code: code,
      name: name,
      content: questionsHtml,
      details: details,
      created_at: new Date().toISOString()
    };
    
    appState.savedExams.push(newExam);
    saveToStorage("saved_exams", appState.savedExams);
    
    showToast(`📜 Saved ${name} to Archives!`, "success");
    
    if (appState.activeView === "vault") {
      renderVaultGrid();
    }
  }

  function deleteVaultPaper(id) {
    appState.savedExams = appState.savedExams.filter(e => e.id !== id);
    saveToStorage("saved_exams", appState.savedExams);
    showToast("🗑️ Scroll deleted from vault.", "danger");
    renderVaultGrid();
    
    const displayArea = document.getElementById("vault-paper-display");
    if (displayArea) {
      displayArea.style.display = "none";
    }
  }

  function handleFileImport(file) {
    if (!file.name.endsWith(".json")) {
      showToast("❌ Only B.Pharm scroll files (.json) are allowed!", "danger");
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target.result);
        
        if (!data.name || !data.code || !data.content || !data.type) {
          showToast("❌ Invalid scroll file structure!", "danger");
          return;
        }

        const id = "exam_" + Date.now() + "_" + Math.random().toString(36).substr(2, 9);
        const importedExam = {
          id: id,
          type: "Imported",
          code: data.code,
          name: data.name,
          content: data.content,
          details: data.details || {},
          created_at: new Date().toISOString()
        };

        appState.savedExams.push(importedExam);
        saveToStorage("saved_exams", appState.savedExams);

        showToast(`📥 Successfully imported ${data.name}!`, "success");
        
        const uploadCard = document.getElementById("vault-upload-card");
        if (uploadCard) uploadCard.style.display = "none";
        
        if (appState.activeView === "vault") {
          renderVaultGrid();
        }
      } catch (err) {
        showToast("❌ Error parsing the JSON file!", "danger");
        console.error(err);
      }
    };
    reader.readAsText(file);
  }

  function renderVaultGrid() {
    const grid = document.getElementById("vault-grid");
    const statsLabel = document.getElementById("vault-stats-label");
    
    if (!grid) return;
    
    grid.innerHTML = "";
    
    const count = appState.savedExams ? appState.savedExams.length : 0;
    if (statsLabel) {
      statsLabel.textContent = `Saved Scrolls: ${count}`;
    }
    
    if (count === 0) {
      grid.innerHTML = `
        <div style="grid-column: 1 / -1; text-align: center; padding: 3rem 1.5rem; background: rgba(255,255,255,0.02); border: 1px dashed var(--card-border); border-radius: var(--radius-md);" class="text-secondary">
          <svg viewBox="0 0 24 24" width="48" height="48" stroke="var(--text-secondary)" fill="none" stroke-width="1.5" style="margin: 0 auto 1rem auto; display: block; opacity: 0.5;"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="9" y1="15" x2="15" y2="15"></line><line x1="9" y1="11" x2="15" y2="11"></line><line x1="9" y1="18" x2="10" y2="18"></line></svg>
          <p style="margin: 0; font-weight: 700; font-size: 1.1rem; color: var(--text-primary);">No scrolls sealed in archives yet</p>
          <p style="margin: 0.5rem 0 0 0; font-size: 0.85rem;">Generate a mock exam, search past memory papers, or click "Upload Custom Paper" to start compiling your study vault.</p>
        </div>
      `;
      return;
    }
    
    appState.savedExams.forEach(exam => {
      const card = document.createElement("div");
      card.className = "archive-card";
      card.setAttribute("data-id", exam.id);
      
      let badgeClass = "badge-mock";
      if (exam.type === "Memory Paper") badgeClass = "badge-past";
      if (exam.type === "Manual Sessional" || exam.type === "Imported") badgeClass = "badge-uploaded";
      if (exam.type === "Photo") badgeClass = "badge-uploaded";
      if (exam.type === "PDF") badgeClass = "badge-past";
      
      const semText = exam.details?.semester || exam.details?.sem || "Unknown Sem";
      const yearText = exam.details?.year || new Date(exam.created_at).toLocaleDateString();
      
      card.innerHTML = `
        <div class="archive-card-header">
          <span class="paper-type-badge ${badgeClass}">${exam.type}</span>
          <span class="paper-code">${exam.code}</span>
          <h3>${exam.name}</h3>
        </div>
        <div class="archive-card-meta">
          <span>${semText}</span>
          <span>${yearText}</span>
        </div>
        <div class="archive-card-actions">
          <button class="btn btn-primary btn-sm btn-open-card" style="padding: 0.35rem 0.75rem; font-size: 0.75rem; flex: 1;">Open Scroll 📜</button>
          <button class="btn btn-secondary btn-sm btn-delete-card" style="padding: 0.35rem 0.75rem; font-size: 0.75rem; color: var(--danger); border-color: rgba(220, 38, 38, 0.2); background: rgba(220, 38, 38, 0.05);">Delete</button>
        </div>
      `;
      
      card.querySelector(".btn-open-card").addEventListener("click", (e) => {
        e.stopPropagation();
        openVaultPaper(exam.id);
      });
      
      card.querySelector(".btn-delete-card").addEventListener("click", (e) => {
        e.stopPropagation();
        if (confirm(`Are you sure you want to delete "${exam.name}" from your vault?`)) {
          deleteVaultPaper(exam.id);
        }
      });
      
      card.addEventListener("click", () => {
        openVaultPaper(exam.id);
      });
      
      grid.appendChild(card);
    });
  }

  function openVaultPaper(id) {
    const exam = appState.savedExams.find(e => e.id === id);
    if (!exam) return;
    
    const displayArea = document.getElementById("vault-paper-display");
    const titleEl = document.getElementById("vault-opened-title");
    const contentEl = document.getElementById("vault-printable-paper-content");
    
    if (!displayArea || !titleEl || !contentEl) return;
    
    titleEl.textContent = `${exam.code} - ${exam.name}`;
    
    const semText = exam.details?.semester || exam.details?.sem || "";
    const yearText = exam.details?.year || "";
    
    let metaHeader = `
      <div style="text-align: center; border-bottom: 2px solid var(--card-border); padding-bottom: 1rem; margin-bottom: 1.5rem;">
        <h3 style="margin: 0; font-size: 1.3rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.5px; border: none; color: var(--accent);">${exam.type}</h3>
        <div style="display: flex; justify-content: space-between; margin-top: 1rem; font-size: 0.85rem; font-weight: 600; color: var(--text-secondary); text-transform: uppercase;">
          <span>Code: ${exam.code}</span>
          <span>${semText}</span>
        </div>
      </div>
      <div style="margin-bottom: 1.5rem; font-size: 0.95rem; line-height: 1.5;">
        <strong>Subject:</strong> <span>${exam.name}</span><br>
        <strong>Created:</strong> <span>${new Date(exam.created_at).toLocaleString()}</span>
        ${yearText ? `<br><strong>Session / Year:</strong> <span>${yearText}</span>` : ""}
      </div>
    `;
    
    let paperBody = "";
    if (exam.type === "Photo") {
      paperBody = `
        <div style="text-align: center; margin-top: 1.5rem;" class="no-print">
          <img src="${exam.content}" style="max-width: 100%; max-height: 80vh; border-radius: var(--radius-md); box-shadow: var(--shadow-md); border: 1px solid var(--card-border);" alt="Saved Photo Scroll">
        </div>
        <div class="print-only" style="display: none;">
          <img src="${exam.content}" style="width: 100%; max-height: 100%; object-fit: contain;">
        </div>
      `;
    } else if (exam.type === "PDF") {
      paperBody = `
        <div style="text-align: center; margin-top: 1.5rem; padding: 2rem; background: rgba(0,0,0,0.2); border: 1px solid var(--card-border); border-radius: var(--radius-md);" class="no-print">
          <svg viewBox="0 0 24 24" width="64" height="64" stroke="var(--danger)" fill="none" stroke-width="1.5" style="margin: 0 auto 1.5rem auto; display: block;"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><path d="M16 13H8"></path><path d="M16 17H8"></path><path d="M10 9H8"></path></svg>
          <h4 style="margin-bottom: 0.5rem; color: var(--text-primary); border: none; padding: 0;">PDF Document Attached</h4>
          <p style="font-size: 0.85rem; color: var(--text-secondary); margin-bottom: 1.5rem;">Use the options below to open the PDF in a new tab or download it directly.</p>
          <div style="display: flex; justify-content: center; gap: 1rem; flex-wrap: wrap;">
            <button class="btn btn-primary" id="vault-opened-btn-view-pdf" style="padding: 0.55rem 1.5rem;">Open PDF in New Tab ↗️</button>
            <a href="${exam.content}" download="${exam.code.replace(/\s+/g, '_')}_document.pdf" class="btn btn-secondary" style="padding: 0.55rem 1.5rem; text-decoration: none; display: inline-flex; align-items: center; justify-content: center; color: var(--text-primary);">Download PDF 📥</a>
          </div>
        </div>
        <div style="margin-top: 1.5rem;" class="no-print">
          <embed src="${exam.content}" type="application/pdf" width="100%" height="600px" style="border-radius: var(--radius-md); border: 1px solid var(--card-border);">
        </div>
        <div class="print-only" style="display: none; text-align: center; padding: 3rem; border: 1px solid #000; color: #000;">
          <h3>PDF Document Attached: ${exam.code} - ${exam.name}</h3>
          <p>Please print this document directly from your PDF reader after downloading or opening it in a new tab.</p>
        </div>
      `;
    } else {
      paperBody = `<div style="margin-top: 1.5rem;">${exam.content}</div>`;
    }

    contentEl.innerHTML = metaHeader + paperBody;
    
    if (exam.type === "PDF") {
      const viewPdfBtn = document.getElementById("vault-opened-btn-view-pdf");
      if (viewPdfBtn) {
        viewPdfBtn.addEventListener("click", () => {
          const newTab = window.open();
          if (newTab) {
            newTab.document.write(`
              <html>
                <head>
                  <title>${exam.code} - ${exam.name}</title>
                  <style>body { margin: 0; padding: 0; background: #525659; }</style>
                </head>
                <body>
                  <embed src="${exam.content}" type="application/pdf" width="100%" height="100%">
                </body>
              </html>
            `);
          } else {
            showToast("❌ Popup blocked! Please allow popups for this site.", "danger");
          }
        });
      }
    }

    displayArea.style.display = "block";
    displayArea.scrollIntoView({ behavior: "smooth" });
    
    const printBtn = document.getElementById("vault-btn-print-opened");
    if (printBtn) {
      printBtn.replaceWith(printBtn.cloneNode(true));
      const activePrint = document.getElementById("vault-btn-print-opened");
      activePrint.addEventListener("click", () => {
        const printable = document.getElementById("printable-cheatsheet");
        if (!printable) return;
        
        let printBody = "";
        if (exam.type === "Photo") {
          printBody = `
            <div style="text-align: center; margin-top: 1.5rem;">
              <img src="${exam.content}" style="width: 100%; max-height: 100%; object-fit: contain;">
            </div>
          `;
        } else if (exam.type === "PDF") {
          printBody = `
            <div style="text-align: center; padding: 3rem; border: 1px solid #000; color: #000;">
              <h3>PDF Document Attached: ${exam.code} - ${exam.name}</h3>
              <p>Please print this document directly from your PDF reader after downloading or opening it in a new tab.</p>
            </div>
          `;
        } else {
          printBody = exam.content;
        }

        printable.innerHTML = `
          <div style="text-align: center; border-bottom: 2px solid #000000; padding-bottom: 1rem; margin-bottom: 1.5rem; color: #000000;">
            <h3 style="margin: 0; font-size: 1.3rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.5px;">Dr. Babasaheb Ambedkar Technological University</h3>
            <h4 style="margin: 0.25rem 0; font-size: 1.05rem; font-weight: 700;">${exam.type} - Archives Vault</h4>
            <div style="display: flex; justify-content: space-between; margin-top: 1rem; font-size: 0.85rem; font-weight: 600; text-transform: uppercase;">
              <span>${exam.code}</span>
              <span>${semText}</span>
            </div>
          </div>
          <div style="margin-bottom: 1.5rem; font-size: 0.95rem; line-height: 1.4; color: #000000;">
            <strong>Subject:</strong> <span>${exam.name}</span><br>
            <strong>Date Generated/Logged:</strong> <span>${new Date(exam.created_at).toLocaleDateString()}</span>
            ${yearText ? `<br><strong>Exam Session:</strong> <span>${yearText}</span>` : ""}
          </div>
          <div style="color: #000000;">
            ${printBody}
          </div>
          <div style="text-align: center; border-top: 1px solid #dddddd; padding-top: 0.8rem; margin-top: 2rem; font-size: 0.75rem; color: #666;">
            <p>Sealed & Retrieved from Ashborn Rx Archives. Prepared under DBATU regulations.</p>
          </div>
        `;
        
        window.print();
      });
    }

    const exportBtn = document.getElementById("vault-btn-export-opened");
    if (exportBtn) {
      exportBtn.replaceWith(exportBtn.cloneNode(true));
      const activeExport = document.getElementById("vault-btn-export-opened");
      activeExport.addEventListener("click", () => {
        const exportData = {
          code: exam.code,
          name: exam.name,
          type: exam.type,
          content: exam.content,
          details: exam.details,
          created_at: exam.created_at
        };
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
        const downloadAnchor = document.createElement("a");
        downloadAnchor.setAttribute("href", dataStr);
        downloadAnchor.setAttribute("download", `${exam.code.replace(/\s+/g, "_")}_scroll.json`);
        document.body.appendChild(downloadAnchor);
        downloadAnchor.click();
        downloadAnchor.remove();
        showToast("📥 Scroll exported successfully!", "success");
      });
    }

    const closeBtn = document.getElementById("vault-btn-close-opened");
    if (closeBtn) {
      closeBtn.replaceWith(closeBtn.cloneNode(true));
      const activeClose = document.getElementById("vault-btn-close-opened");
      activeClose.addEventListener("click", () => {
        displayArea.style.display = "none";
      });
    }
  }

  function initVaultView() {
    renderVaultGrid();
    
    const displayArea = document.getElementById("vault-paper-display");
    if (displayArea) displayArea.style.display = "none";
    
    const uploadCard = document.getElementById("vault-upload-card");
    if (uploadCard) uploadCard.style.display = "none";
    
    const toggleUploadBtn = document.getElementById("vault-btn-toggle-upload");
    const closeUploadBtn = document.getElementById("vault-btn-close-upload");
    
    if (toggleUploadBtn && uploadCard) {
      toggleUploadBtn.replaceWith(toggleUploadBtn.cloneNode(true));
      const activeToggle = document.getElementById("vault-btn-toggle-upload");
      activeToggle.addEventListener("click", () => {
        if (uploadCard.style.display === "none") {
          uploadCard.style.display = "block";
          uploadCard.scrollIntoView({ behavior: "smooth" });
        } else {
          uploadCard.style.display = "none";
        }
      });
    }

    if (closeUploadBtn && uploadCard) {
      closeUploadBtn.replaceWith(closeUploadBtn.cloneNode(true));
      const activeClose = document.getElementById("vault-btn-close-upload");
      activeClose.addEventListener("click", () => {
        uploadCard.style.display = "none";
      });
    }

    const tabBtnManual = document.getElementById("vault-tab-btn-manual");
    const tabBtnImport = document.getElementById("vault-tab-btn-import");
    const tabBtnMedia = document.getElementById("vault-tab-btn-media");
    const manualForm = document.getElementById("vault-manual-form");
    const importPanel = document.getElementById("vault-import-panel");
    const mediaForm = document.getElementById("vault-media-form");

    if (tabBtnManual && tabBtnImport && tabBtnMedia && manualForm && importPanel && mediaForm) {
      tabBtnManual.replaceWith(tabBtnManual.cloneNode(true));
      tabBtnImport.replaceWith(tabBtnImport.cloneNode(true));
      tabBtnMedia.replaceWith(tabBtnMedia.cloneNode(true));
      
      const activeTabManual = document.getElementById("vault-tab-btn-manual");
      const activeTabImport = document.getElementById("vault-tab-btn-import");
      const activeTabMedia = document.getElementById("vault-tab-btn-media");

      const showTab = (tab) => {
        activeTabManual.classList.remove("active");
        activeTabImport.classList.remove("active");
        activeTabMedia.classList.remove("active");
        
        manualForm.style.display = "none";
        importPanel.style.display = "none";
        mediaForm.style.display = "none";
        
        if (tab === "manual") {
          activeTabManual.classList.add("active");
          manualForm.style.display = "flex";
        } else if (tab === "import") {
          activeTabImport.classList.add("active");
          importPanel.style.display = "flex";
        } else if (tab === "media") {
          activeTabMedia.classList.add("active");
          mediaForm.style.display = "flex";
        }
      };

      activeTabManual.addEventListener("click", () => showTab("manual"));
      activeTabImport.addEventListener("click", () => showTab("import"));
      activeTabMedia.addEventListener("click", () => showTab("media"));
    }

    const clearAllBtn = document.getElementById("vault-btn-clear-all");
    if (clearAllBtn) {
      clearAllBtn.replaceWith(clearAllBtn.cloneNode(true));
      const activeClear = document.getElementById("vault-btn-clear-all");
      activeClear.addEventListener("click", () => {
        if (confirm("⚠️ Are you sure you want to PURGE all scrolls from your archives? This cannot be undone!")) {
          appState.savedExams = [];
          saveToStorage("saved_exams", []);
          showToast("🚫 Archives successfully purged!", "danger");
          renderVaultGrid();
          if (displayArea) displayArea.style.display = "none";
        }
      });
    }

    const form = document.getElementById("vault-manual-form");
    if (form) {
      form.replaceWith(form.cloneNode(true));
      const activeForm = document.getElementById("vault-manual-form");
      activeForm.addEventListener("submit", (e) => {
        e.preventDefault();
        
        const name = document.getElementById("vault-input-name").value.trim();
        const code = document.getElementById("vault-input-code").value.trim();
        const sem = document.getElementById("vault-input-sem").value;
        const year = document.getElementById("vault-input-year").value.trim();
        const rawContent = document.getElementById("vault-input-content").value;
        
        let questionsHtml = "";
        const lines = rawContent.split("\n").map(l => l.trim()).filter(Boolean);
        if (lines.length > 0) {
          questionsHtml = `<div class="manual-paper-rendered" style="line-height: 1.6;">`;
          questionsHtml += `<h4 style="border-bottom: 1px solid var(--card-border); padding-bottom: 0.25rem; margin-bottom: 0.75rem; color: var(--accent);">QUESTION PAPER</h4>`;
          questionsHtml += `<ol style="margin-left: 1.5rem;">`;
          lines.forEach(line => {
            const cleanLine = line.replace(/^\d+[\.\)\s\-]\s*/, "");
            questionsHtml += `<li style="margin-bottom: 0.5rem;">${cleanLine}</li>`;
          });
          questionsHtml += `</ol></div>`;
        }
        
        saveExamToVault("Manual Sessional", code, name, questionsHtml, {
          semester: sem,
          year: year,
          timestamp: new Date().toISOString()
        });
        
        activeForm.reset();
        if (uploadCard) uploadCard.style.display = "none";
      });
    }

    const dragDropZone = document.getElementById("vault-drag-drop-zone");
    const fileInput = document.getElementById("vault-file-input");

    if (dragDropZone && fileInput) {
      dragDropZone.replaceWith(dragDropZone.cloneNode(true));
      const activeZone = document.getElementById("vault-drag-drop-zone");
      
      activeZone.addEventListener("click", () => {
        const currentInput = document.getElementById("vault-file-input");
        if (currentInput) currentInput.click();
      });

      activeZone.addEventListener("dragover", (e) => {
        e.preventDefault();
        activeZone.classList.add("dragover");
      });

      activeZone.addEventListener("dragleave", () => {
        activeZone.classList.remove("dragover");
      });

      activeZone.addEventListener("drop", (e) => {
        e.preventDefault();
        activeZone.classList.remove("dragover");
        if (e.dataTransfer.files.length > 0) {
          handleFileImport(e.dataTransfer.files[0]);
        }
      });
      
      fileInput.replaceWith(fileInput.cloneNode(true));
      const activeFileInput = document.getElementById("vault-file-input");
      activeFileInput.addEventListener("click", (e) => {
        e.stopPropagation();
      });
      activeFileInput.addEventListener("change", (e) => {
        if (e.target.files.length > 0) {
          handleFileImport(e.target.files[0]);
        }
      });
    }

    // --- PHOTO / PDF MEDIA UPLOAD HANDLERS ---
    const mediaDropZone = document.getElementById("vault-media-drop-zone");
    const mediaFileInput = document.getElementById("vault-media-file-input");
    const mediaFormEl = document.getElementById("vault-media-form");
    const mediaSubmitBtn = document.getElementById("vault-media-btn-submit");

    let selectedMediaFile = null;
    let selectedMediaDataUrl = null;
    let selectedMediaType = null;

    if (mediaDropZone && mediaFileInput && mediaFormEl && mediaSubmitBtn) {
      // Clone to clear prior listeners
      mediaDropZone.replaceWith(mediaDropZone.cloneNode(true));
      mediaFileInput.replaceWith(mediaFileInput.cloneNode(true));
      mediaFormEl.replaceWith(mediaFormEl.cloneNode(true));

      const activeDropZone = document.getElementById("vault-media-drop-zone");
      const activeFileInput = document.getElementById("vault-media-file-input");
      const activeFormEl = document.getElementById("vault-media-form");
      const activeSubmitBtn = document.getElementById("vault-media-btn-submit");
      const activePreviewContainer = document.getElementById("vault-media-preview-container");
      const activeRemoveBtn = document.getElementById("vault-media-btn-remove-file");
      
      activeDropZone.addEventListener("click", () => {
        const currentMediaInput = document.getElementById("vault-media-file-input");
        if (currentMediaInput) currentMediaInput.click();
      });

      activeDropZone.addEventListener("dragover", (e) => {
        e.preventDefault();
        activeDropZone.style.borderColor = "var(--accent)";
        activeDropZone.style.background = "rgba(251, 191, 36, 0.05)";
      });

      const resetZoneStyle = () => {
        activeDropZone.style.borderColor = "var(--card-border)";
        activeDropZone.style.background = "transparent";
      };

      activeDropZone.addEventListener("dragleave", resetZoneStyle);
      activeDropZone.addEventListener("drop", (e) => {
        e.preventDefault();
        resetZoneStyle();
        if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length > 0) {
          processSelectedMedia(e.dataTransfer.files[0]);
        }
      });

      activeFileInput.addEventListener("click", (e) => {
        e.stopPropagation();
      });

      activeFileInput.addEventListener("change", (e) => {
        if (e.target && e.target.files && e.target.files.length > 0) {
          processSelectedMedia(e.target.files[0]);
        }
      });

      if (activeRemoveBtn) {
        activeRemoveBtn.addEventListener("click", () => {
          selectedMediaFile = null;
          selectedMediaDataUrl = null;
          selectedMediaType = null;
          if (activePreviewContainer) activePreviewContainer.style.display = "none";
          if (activeSubmitBtn) activeSubmitBtn.disabled = true;
          activeFileInput.value = "";
        });
      }

      activeFormEl.addEventListener("submit", (e) => {
        e.preventDefault();
        if (!selectedMediaDataUrl || !selectedMediaType) return;

        const name = document.getElementById("vault-media-input-name").value.trim();
        const code = document.getElementById("vault-media-input-code").value.trim();
        const sem = document.getElementById("vault-media-input-sem").value;
        const year = document.getElementById("vault-media-input-year").value.trim();

        saveExamToVault(selectedMediaType, code, name, selectedMediaDataUrl, {
          semester: sem,
          year: year,
          filename: selectedMediaFile.name,
          timestamp: new Date().toISOString()
        });

        selectedMediaFile = null;
        selectedMediaDataUrl = null;
        selectedMediaType = null;
        if (activePreviewContainer) activePreviewContainer.style.display = "none";
        if (activeSubmitBtn) activeSubmitBtn.disabled = true;
        activeFormEl.reset();
        if (uploadCard) uploadCard.style.display = "none";
      });
    }

    function processSelectedMedia(file) {
      if (!file) return;

      const fileNameLower = file.name.toLowerCase();
      const isImage = file.type.startsWith("image/") || 
                      fileNameLower.endsWith(".png") || 
                      fileNameLower.endsWith(".jpg") || 
                      fileNameLower.endsWith(".jpeg") || 
                      fileNameLower.endsWith(".webp") || 
                      fileNameLower.endsWith(".gif") || 
                      fileNameLower.endsWith(".bmp");
      const isPdf = file.type === "application/pdf" || 
                    fileNameLower.endsWith(".pdf");

      if (!isImage && !isPdf) {
        showToast("❌ Only photos (images) and PDFs are allowed!", "danger");
        return;
      }

      if (isPdf) {
        if (file.size > 1.5 * 1024 * 1024) {
          alert(`⚠️ PDF file is too large (${(file.size / 1024 / 1024).toFixed(2)}MB). To prevent browser local storage limit issues, please choose a PDF file smaller than 1.5MB.`);
          return;
        }

        selectedMediaFile = file;
        selectedMediaType = "PDF";
        
        const reader = new FileReader();
        reader.onload = (e) => {
          selectedMediaDataUrl = e.target.result;
          displayMediaPreview();
        };
        reader.readAsDataURL(file);
      } else if (isImage) {
        selectedMediaFile = file;
        selectedMediaType = "Photo";

        const reader = new FileReader();
        reader.onload = (e) => {
          const img = new Image();
          img.onload = () => {
            const canvas = document.createElement("canvas");
            let width = img.width;
            let height = img.height;
            const MAX_WIDTH = 1200;
            const MAX_HEIGHT = 1200;

            if (width > height) {
              if (width > MAX_WIDTH) {
                height *= MAX_WIDTH / width;
                width = MAX_WIDTH;
              }
            } else {
              if (height > MAX_HEIGHT) {
                width *= MAX_HEIGHT / height;
                height = MAX_HEIGHT;
              }
            }

            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext("2d");
            ctx.drawImage(img, 0, 0, width, height);

            selectedMediaDataUrl = canvas.toDataURL("image/jpeg", 0.7);
            displayMediaPreview();
          };
          img.src = e.target.result;
        };
        reader.readAsDataURL(file);
      }
    }

    function displayMediaPreview() {
      if (!selectedMediaFile || !selectedMediaDataUrl) return;

      const activeFilename = document.getElementById("vault-media-preview-filename");
      const activeFilesize = document.getElementById("vault-media-preview-filesize");
      const activeThumbnail = document.getElementById("vault-media-preview-thumbnail");
      const activeContainer = document.getElementById("vault-media-preview-container");
      const activeSubmitBtn = document.getElementById("vault-media-btn-submit");

      if (activeFilename) activeFilename.textContent = selectedMediaFile.name;
      
      const sizeMB = selectedMediaFile.size / 1024 / 1024;
      if (activeFilesize) {
        activeFilesize.textContent = sizeMB >= 1 
          ? `${sizeMB.toFixed(2)} MB` 
          : `${(selectedMediaFile.size / 1024).toFixed(1)} KB`;
      }

      if (activeThumbnail) {
        if (selectedMediaType === "Photo") {
          activeThumbnail.style.backgroundImage = `url(${selectedMediaDataUrl})`;
          activeThumbnail.textContent = "";
        } else {
          activeThumbnail.style.backgroundImage = "none";
          activeThumbnail.innerHTML = `<span style="color: var(--danger); font-weight: 800;">PDF</span>`;
        }
      }

      if (activeContainer) activeContainer.style.display = "flex";
      if (activeSubmitBtn) activeSubmitBtn.disabled = false;
      showToast("📎 File attached successfully!", "success");
    }
  }

  // --- RECEPTOR BINDING ARENA (DOJO) IMPLEMENTATION ---
  
  // Game states & database definition
  const arenaMissions = [
    {
      id: "mission_tachycardia",
      targetReceptor: "GPCR",
      name: "Hypertensive Tachycardia",
      description: "Target: Acute Tachycardia. Bind a selective antagonist to the GPCR (Beta-1 Adrenergic) to block active stimulation and lower heart rate.",
      successCriteria: {
        orthosteric: "metoprolol"
      },
      jutsuReward: "Water Style: Heart Calming Jutsu 🌊"
    },
    {
      id: "mission_anxiety",
      targetReceptor: "GABA",
      name: "Severe Panic Attack",
      description: "Target: Severe Anxiety. Bind the endogenous agonist (GABA) to the orthosteric site AND a positive allosteric modulator (Diazepam) to the allosteric site to maximize inhibitory chloride currents.",
      successCriteria: {
        orthosteric: "gaba",
        allosteric: "diazepam"
      },
      jutsuReward: "Shadow Clone: Neural Damping Jutsu 🛡️"
    },
    {
      id: "mission_diabetes",
      targetReceptor: "Insulin",
      name: "Hyperglycemia Crisis",
      description: "Target: Type 1 Diabetes. Bind the endogenous hormone agonist (Insulin) to both receptor subunits to trigger autophosphorylation and translocate glucose transport channels (GLUT-4) to the membrane.",
      successCriteria: {
        subunit_a: "insulin",
        subunit_b: "insulin"
      },
      jutsuReward: "Fire Style: Metabolic Surge Jutsu 🔥"
    }
  ];

  const arenaLigands = [
    { id: "epinephrine", name: "Epinephrine (Agonist)", type: "Agonist", color: "#f59e0b", formula: "C9H13NO3" },
    { id: "metoprolol", name: "Metoprolol (Beta-Blocker)", type: "Antagonist", color: "#ef4444", formula: "C15H25NO3" },
    { id: "gaba", name: "GABA (Endogenous Agonist)", type: "Agonist", color: "#3b82f6", formula: "C4H9NO2" },
    { id: "diazepam", name: "Diazepam (Benzodiazepine)", type: "Allosteric Modulator", color: "#a855f7", formula: "C16H13ClN2O" },
    { id: "flumazenil", name: "Flumazenil (BZD Antagonist)", type: "Antagonist", color: "#f43f5e", formula: "C15H14FN3O3" },
    { id: "insulin", name: "Insulin (Hormone Agonist)", type: "Agonist", color: "#10b981", formula: "51 Amino Acids" }
  ];

  // Initialize State structure if missing
  if (!appState.arena) {
    appState.arena = {
      activeReceptor: "GPCR", // "GPCR", "GABA", "Insulin"
      activeMissionIndex: 0,
      boundLigands: {}, // e.g. { orthosteric: "metoprolol" }
      selectedLigandId: null
    };
  }

  function initArenaView() {
    renderActiveMission();
    renderReceptorTabs();
    renderLigandTray();
    renderReceptorVisual();
    setupArenaListeners();
  }

  function renderActiveMission() {
    const missionDesc = document.getElementById("arena-mission-desc");
    const missionNum = document.getElementById("arena-mission-number");
    
    if (!missionDesc || !missionNum) return;

    const mission = arenaMissions[appState.arena.activeMissionIndex];
    missionNum.textContent = `Mission ${appState.arena.activeMissionIndex + 1}/${arenaMissions.length}`;
    missionDesc.textContent = `${mission.name} - ${mission.description}`;
    
    // Auto-toggle to the correct target receptor for the active mission
    if (appState.arena.activeReceptor !== mission.targetReceptor) {
      appState.arena.activeReceptor = mission.targetReceptor;
      appState.arena.boundLigands = {};
    }
  }

  function renderReceptorTabs() {
    const tabGpcr = document.getElementById("arena-tab-gpcr");
    const tabGaba = document.getElementById("arena-tab-gaba");
    const tabInsulin = document.getElementById("arena-tab-insulin");

    if (!tabGpcr || !tabGaba || !tabInsulin) return;

    [tabGpcr, tabGaba, tabInsulin].forEach(tab => tab.classList.remove("active"));

    if (appState.arena.activeReceptor === "GPCR") tabGpcr.classList.add("active");
    else if (appState.arena.activeReceptor === "GABA") tabGaba.classList.add("active");
    else if (appState.arena.activeReceptor === "Insulin") tabInsulin.classList.add("active");
  }

  function renderLigandTray() {
    const tray = document.getElementById("arena-ligand-tray");
    if (!tray) return;

    tray.innerHTML = arenaLigands.map(l => {
      const isSelected = appState.arena.selectedLigandId === l.id ? "selected" : "";
      return `
        <div class="ligand-card ${isSelected}" draggable="true" id="ligand-${l.id}" data-ligand-id="${l.id}">
          <span class="ligand-color-dot" style="background-color: ${l.color};"></span>
          <div style="flex: 1;">
            <strong style="display: block; font-size: 0.85rem; color: var(--text-primary);">${l.name}</strong>
            <span style="font-size: 0.7rem; color: var(--text-secondary); font-family: monospace;">Formula: ${l.formula}</span>
          </div>
          <span style="font-size: 0.7rem; padding: 0.15rem 0.4rem; border-radius: 4px; background: rgba(255,255,255,0.05); color: var(--text-secondary); font-weight: 600;">${l.type}</span>
        </div>
      `;
    }).join("");

    // Attach dragstart and click listeners
    tray.querySelectorAll(".ligand-card").forEach(card => {
      card.addEventListener("dragstart", (e) => {
        e.dataTransfer.setData("text/plain", card.getAttribute("data-ligand-id"));
        card.classList.add("dragging");
      });
      card.addEventListener("dragend", () => {
        card.classList.remove("dragging");
      });
      card.addEventListener("click", () => {
        const clickedId = card.getAttribute("data-ligand-id");
        if (appState.arena.selectedLigandId === clickedId) {
          appState.arena.selectedLigandId = null;
        } else {
          appState.arena.selectedLigandId = clickedId;
        }
        renderLigandTray();
        renderReceptorVisual(); // Highlights target pockets
      });
    });
  }

  function renderReceptorVisual() {
    const canvas = document.getElementById("arena-visual-canvas");
    if (!canvas) return;

    // Reset view
    canvas.innerHTML = "";

    const activeRec = appState.arena.activeReceptor;

    // Create Membrane Bilayer
    const bilayer = document.createElement("div");
    bilayer.className = "membrane-bilayer";
    canvas.appendChild(bilayer);

    if (activeRec === "GPCR") {
      renderGpcrModel(canvas);
    } else if (activeRec === "GABA") {
      renderGabaModel(canvas);
    } else if (activeRec === "Insulin") {
      renderInsulinModel(canvas);
    }

    renderPockets(canvas);
    updateSignalingEffectCard();
  }

  function renderGpcrModel(canvas) {
    // 7TM Serpent Path SVG
    const structure = document.createElement("div");
    structure.className = "receptor-structure";
    structure.style.width = "220px";
    structure.style.height = "260px";
    structure.style.position = "relative";

    // Bind state styles
    const isAgonistBound = appState.arena.boundLigands["orthosteric"] === "epinephrine";
    const isAntagonistBound = appState.arena.boundLigands["orthosteric"] === "metoprolol";
    const activePulseClass = isAgonistBound ? "gpcr-active-pulse" : "";

    structure.innerHTML = `
      <svg viewBox="0 0 200 240" style="width: 100%; height: 100%;" class="${activePulseClass}">
        <!-- Extracellular Loops -->
        <path d="M 20 80 Q 35 60 50 80 T 80 80 T 110 80 T 140 80 T 170 80" fill="none" stroke="rgba(255,255,255,0.2)" stroke-width="6"/>
        
        <!-- 7 Transmembrane Cylinders (helices) -->
        <g stroke="var(--accent)" stroke-width="2" fill="rgba(251, 191, 36, 0.1)">
          <rect x="15" y="80" width="16" height="120" rx="4" style="fill: ${isAgonistBound ? "rgba(16, 185, 129, 0.3)" : isAntagonistBound ? "rgba(239, 68, 68, 0.3)" : ""}" />
          <rect x="40" y="80" width="16" height="120" rx="4" />
          <rect x="65" y="80" width="16" height="120" rx="4" />
          <rect x="90" y="80" width="16" height="120" rx="4" />
          <rect x="115" y="80" width="16" height="120" rx="4" />
          <rect x="140" y="80" width="16" height="120" rx="4" />
          <rect x="165" y="80" width="16" height="120" rx="4" />
        </g>

        <!-- Intracellular Loops -->
        <path d="M 25 200 Q 40 220 55 200 T 85 200 T 115 200 T 145 200" fill="none" stroke="rgba(255,255,255,0.2)" stroke-width="6"/>

        <!-- Intracellular G-Protein Subunit -->
        <g class="g-alpha-subunit ${isAgonistBound ? "activated" : ""}" id="g-protein-alpha" fill="#f59e0b" transform="translate(0, 0)">
          <circle cx="98" cy="225" r="14" fill="#a855f7" opacity="0.8"/>
          <text x="98" y="228" font-size="8" fill="#fff" text-anchor="middle" font-weight="bold">Gα</text>
        </g>
        <circle cx="120" cy="235" r="11" fill="#3b82f6" opacity="0.6"/>
        <text x="120" y="238" font-size="7" fill="#fff" text-anchor="middle">Gβ</text>
        <circle cx="132" cy="242" r="9" fill="#10b981" opacity="0.6"/>
      </svg>
    `;
    canvas.appendChild(structure);
  }

  function renderGabaModel(canvas) {
    // Pentameric pentagon channel
    const structure = document.createElement("div");
    structure.className = "receptor-structure";
    structure.style.width = "220px";
    structure.style.height = "260px";
    structure.style.position = "relative";

    const isAgonist = appState.arena.boundLigands["orthosteric"] === "gaba";
    const isAllosteric = appState.arena.boundLigands["allosteric"] === "diazepam";

    structure.innerHTML = `
      <svg viewBox="0 0 200 240" style="width: 100%; height: 100%;">
        <!-- Pentamer pore structure side profile -->
        <g stroke="rgba(59, 130, 246, 0.4)" stroke-width="3" fill="rgba(59, 130, 246, 0.1)">
          <!-- Left and Right pore gates -->
          <path d="M 60 70 L 60 170 C 60 180 80 180 80 170 L 80 70 Z" style="fill: ${isAgonist && isAllosteric ? "rgba(16, 185, 129, 0.25)" : isAgonist ? "rgba(59, 130, 246, 0.25)" : ""}"/>
          <path d="M 140 70 L 140 170 C 140 180 120 180 120 170 L 120 70 Z" style="fill: ${isAgonist && isAllosteric ? "rgba(16, 185, 129, 0.25)" : isAgonist ? "rgba(59, 130, 246, 0.25)" : ""}"/>
        </g>
        
        <!-- Central Pore Opening -->
        <line x1="100" y1="70" x2="100" y2="170" stroke="rgba(255,255,255,0.2)" stroke-width="8" stroke-dasharray="4"/>
      </svg>
    `;

    canvas.appendChild(structure);

    // Create flowing Chloride Ion Bubbles if channel is active
    if (isAgonist) {
      const streamCount = isAllosteric ? 12 : 5; // modulators open the pore much wider!
      for (let i = 0; i < streamCount; i++) {
        const bubble = document.createElement("div");
        bubble.className = "ion-bubble streaming";
        bubble.style.left = `${110 + (Math.random() * 10 - 5)}px`;
        bubble.style.top = "140px";
        bubble.style.animationDelay = `${i * 0.3}s`;
        structure.appendChild(bubble);
      }
    }
  }

